def refs():
    return [{**s, "subject": "science", "locator": "生產者、消費者、分解者、非生物因子、能量流轉、物質循環與生態系穩定", "observedPattern": "公開公立學校生物資料常用池塘、食物網、分解者與能量／物質圖示判讀生態角色；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bd-iv-3-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開生物科資料僅供生態角色、非生物環境、分解與能量／物質路徑的能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開公立學校生物科資料的能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "池塘中的藻類利用光能製造有機物，牠在生態系中主要扮演什麼角色？", {"A": "生產者", "B": "初級消費者", "C": "分解者", "D": "非生物因子"}, "A", "藻類能自行製造有機物，是能量進入食物網的生產者，選 A。", "先看生物是否能自行製造有機物，再判斷營養角色。", ["確認藻類是生物。", "它利用光能與無機物合成有機物。", "能自行製造養分的生物是生產者。", "消費者需攝食，非生物因子不是生物。", "所以選 A。"], "easy"),
    make(2, "細菌和真菌分解落葉時，對生態系最重要的功能是？", {"A": "把有機物分解並使養分回到環境", "B": "把所有能量重新變成陽光", "C": "停止植物的光合作用", "D": "只增加捕食者數量而不影響物質"}, "A", "分解者利用遺體與排遺，將有機物拆解，使部分養分回到土壤、水和大氣，選 A。", "將分解者作用拆成『取得能量』和『養分回流』兩條結果。", ["落葉含有生物合成的有機物。", "細菌和真菌利用並分解這些物質。", "碳、氮等元素可回到環境。", "能量仍會以熱散失，不會變回陽光。", "因此選 A。"], "easy"),
    make(3, "下列何者屬於非生物因子，卻會影響池塘生物的分布？", {"A": "水溫", "B": "水草", "C": "蝌蚪", "D": "細菌"}, "A", "水溫不是生物，但會影響代謝、溶氧與生物適存範圍，選 A。", "先用『是否具有生命』區分生物和非生物，再判斷其作用。", ["檢查各選項是否能生長、繁殖或代謝。", "水草、蝌蚪和細菌是生物。", "水溫是環境的物理條件。", "物理條件會改變生物的生存與活動。", "所以選 A。"], "easy"),
    make(4, "若池塘中的分解者數量大幅下降，短期內最可能先出現哪種變化？", {"A": "枯葉與遺體分解變慢，養分回到水土的速率降低", "B": "太陽能立刻消失", "C": "所有消費者立即變成生產者", "D": "水中所有氧氣必定增加"}, "A", "分解者減少會降低分解速率，遺體和枯葉累積，養分釋放回環境的速度變慢，選 A。", "先找被移除角色的直接功能，再推論相鄰物質路徑。", ["分解者原本處理遺體和排遺。", "數量下降會降低處理量。", "有機殘體可能累積。", "養分回流到環境的速率也會降低。", "所以選 A。"], "medium"),
    make(5, "生產者、消費者和分解者共同存在，最能支持哪項生態系功能？", {"A": "能量沿食物關係傳遞，物質則可在生物與環境間循環", "B": "所有能量都會永久留在生物體內", "C": "分解者使物質離開地球", "D": "生產者不需要環境中的水和二氧化碳"}, "A", "生產者引入能量和有機物，消費者傳遞，分解者使元素回到環境；能量仍會散失，選 A。", "把三類角色各自的功能接成一條能量路徑和一條物質路徑。", ["生產者製造有機物。", "消費者透過攝食取得並傳遞能量。", "分解者讓元素回到環境。", "能量流動和物質循環的方向與性質不同。", "所以選 A。"], "medium"),
    make(6, "農田施用過量肥料後，藻類大量繁殖並可能造成魚群死亡。哪條推理最合理？", {"A": "養分增加促進藻類，分解與呼吸耗氧後可能使魚缺氧", "B": "肥料會讓魚直接變成植物", "C": "藻類增加一定會使水中氧氣永久增加", "D": "魚死亡與分解者完全無關"}, "A", "過量養分可能引起藻類增生；遺體與有機物分解、微生物呼吸會消耗溶氧，導致魚類缺氧，選 A。", "沿『養分→生產者增生→有機物增加→分解耗氧』逐段推理。", ["肥料提供可利用的無機養分。", "藻類增多使水中有機物量增加。", "藻類死亡後由分解者處理。", "分解與呼吸消耗溶氧，魚可能缺氧。", "所以選 A。"], "hard"),
    make(7, "某食物網移除一種捕食者後，不能直接斷言所有獵物都會增加，主要因為？", {"A": "食物網還有其他捕食、競爭和環境限制路徑", "B": "捕食者永遠不影響獵物", "C": "所有獵物都能自行製造養分", "D": "移除一種生物會使太陽能減少"}, "A", "獵物數量還受其他天敵、食物量、疾病和非生物條件限制，不能只看一條連線，選 A。", "把單一因果改成食物網與環境條件的多路徑分析。", ["先找被移除捕食者的直接獵物。", "再檢查其他捕食者和競爭者。", "食物與環境條件也會限制族群。", "因此不能保證所有獵物都增加。", "所以選 A。"], "hard"),
    make(8, "在生態瓶中加入水草、蝸牛、細菌與水，若要描述完整生態系，還應特別考慮哪類因素？", {"A": "光照、溫度和水中溶氧等非生物因子", "B": "只再加入一種消費者即可", "C": "只記錄生物名稱，不需環境資料", "D": "把水當成消費者"}, "A", "生態系包含生物與非生物環境；光照、溫度和溶氧會共同影響各角色，選 A。", "列出完整系統的生物角色後，再補上會限制它們的環境條件。", ["水草、蝸牛和細菌代表不同生物角色。", "光照影響生產者的能量取得。", "溫度與溶氧影響代謝和存活。", "水本身是環境成分，不是消費者。", "所以選 A。"], "medium"),
    make(9, "如果觀察到分解速率在高溫時加快，哪個結論最謹慎？", {"A": "在本次材料、溫度範圍與時間內，高溫組分解較快", "B": "所有分解者在任何高溫都一定更快", "C": "高溫證明分解者不需要水分", "D": "分解速率可直接代表整個生態系健康"}, "A", "實驗結果只能支持特定材料與範圍內的比較；超過適宜範圍仍可能抑制生物活動，選 A。", "把觀察結果綁定測試條件，避免過度外推。", ["指出比較的材料與溫度範圍。", "高溫組在該範圍內分解較快。", "分解者仍受水分、氧氣與極端溫度限制。", "不能把單一速率等同整個生態系健康。", "所以選 A。"], "hard"),
    make(10, "關於生態系中的能量與物質，哪個敘述最完整？", {"A": "能量經生產者和消費者傳遞並散失，元素可經分解等作用回到環境", "B": "能量和元素都會以相同方式無限循環", "C": "分解者只處理能量而不處理物質", "D": "非生物環境不會和生物互動"}, "A", "能量沿營養階層流動並部分以熱散失；分解者使元素回到環境，生物也與非生物條件交互作用，選 A。", "最後用兩條線各自檢核能量去向與元素回流，避免混成同一種循環。", ["生產者先把能量帶入生物系統。", "消費者攝食傳遞部分能量。", "呼吸等作用使能量以熱散失。", "分解者促成元素回到環境並再被利用。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    old = {o["id"]: o["text"] for o in q["options"]}
    old["A"], old[target] = old[target], old["A"]
    q["options"] = [{"id": k, "text": old[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A", f"選 {target}")
    q["solutionStrategy"] = q["solutionStrategy"].replace("選 A", f"選 {target}")
    q["solutionSteps"] = [s.replace("選 A", f"選 {target}").replace("所以選 A", f"所以選 {target}") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
